// 時間複雜度: O(m + n)，空間複雜度: O(min(m, n))
function intersect(nums1, nums2) {
    const count = new Map();
    for (const x of nums1)
        count.set(x, (count.get(x) ?? 0) + 1);
    const result = [];
    for (const x of nums2) {
        const c = count.get(x) ?? 0;
        if (c > 0) {
            result.push(x);
            count.set(x, c - 1);
        }
    }
    return result;
}

