#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    /**
     * 方法一：哈希表計數（推薦）
     * 時間複雜度: O(m + n)
     * 空間複雜度: O(min(m, n))
     */
    vector<int> intersect(vector<int>& nums1, vector<int>& nums2) {
        // 使用較小的陣列建立哈希表
        if (nums1.size() > nums2.size()) {
            return intersect(nums2, nums1);
        }

        // 統計 nums1 中每個數字的頻率
        unordered_map<int, int> count;
        for (int num : nums1) {
            count[num]++;
        }

        vector<int> result;

        // 遍歷 nums2
        for (int num : nums2) {
            if (count[num] > 0) {
                result.push_back(num);
                count[num]--;
            }
        }

        return result;
    }

    /**
     * 方法二：雙指標（適用於已排序陣列）
     * 時間複雜度: O(m log m + n log n)
     * 空間複雜度: O(1)
     */
    vector<int> intersect_twopointers(vector<int>& nums1, vector<int>& nums2) {
        sort(nums1.begin(), nums1.end());
        sort(nums2.begin(), nums2.end());

        int i = 0, j = 0;
        vector<int> result;

        while (i < nums1.size() && j < nums2.size()) {
            if (nums1[i] == nums2[j]) {
                result.push_back(nums1[i]);
                i++;
                j++;
            } else if (nums1[i] < nums2[j]) {
                i++;
            } else {
                j++;
            }
        }

        return result;
    }
};

