// 值域 0~1000，用計數陣列代替雜湊表
// 時間複雜度: O(m + n)，空間複雜度: O(1)（固定 1001 格）
int* intersect(int* nums1, int nums1Size, int* nums2, int nums2Size, int* returnSize) {
    int count[1001] = {0};
    for (int i = 0; i < nums1Size; i++) count[nums1[i]]++;

    int* result = malloc(sizeof(int) * ((nums1Size < nums2Size ? nums1Size : nums2Size) + 1));
    *returnSize = 0;
    for (int i = 0; i < nums2Size; i++) {
        if (count[nums2[i]] > 0) {
            count[nums2[i]]--;
            result[(*returnSize)++] = nums2[i];
        }
    }
    return result;
}

